INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65914818', 65914818, 'analyze_legacy', 'Kementerian Imigrasi dan Pemasyarakatan', 'central', 'DIREKTORAT JENDERAL IMIGRASI', 'Pengadaan Penambah Daya Tahan Tubuh Dit. TIK Kegiatan Alih Pengetahuan di Bidang Teknologi Informasi Pada Direktorat Jenderal Imigrasi Tahun Anggaran 2026', 'Barang', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 684000000, 'May 2026', 'APBN - PNBP (D)', 1, 1, '36000 OK', 'Menyediakan penambah daya tahan tubuh sebagai langkah preventif untuk meminimalisir risiko kelelahan dan penurunan kesehatan akibat pelaksanaan tugas dan fungsi pegawai di lingkungan Direktorat Teknologi Informasi Keimigrasian.', 'Penambah daya tahan tubuh berupa suplemen yang memiliki spesifikasi dasar: - Terdiri dari kombinasi multivitamin atau asupan pendukung lainnya yang telah terdaftar secara resmi di BPOM serta memiliki sertifikasi Halal; - Dikemas secara higienis dalam satuan paket siap konsumsi per orang; - Memiliki masa kedaluwarsa minimal 12 bulan sejak waktu penyerahan; - Dalam kondisi segel yang masih utuh.', 684000000, 'high', 'Pengadaan suplemen/penambah daya tahan tubuh dalam jumlah sangat besar untuk kegiatan alih pengetahuan di bidang TIK tidak tampak sebagai kebutuhan inti pengadaan barang utama. Dari judul, volume, dan anggaran, belanja ini berindikasi kuat tidak proporsional terhadap tujuan kegiatan serta berpotensi menjadi belanja konsumtif yang seharusnya dibatasi atau tidak dibebankan penuh.', NULL, NULL, 3, 1, 1, 1, 1, 2411426);
