INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65919143', 65919143, 'analyze_legacy', 'Badan Pengawasan Keuangan Dan Pembangunan', 'central', 'PUSAT INFORMASI PENGAWASAN BADAN PENGAWASAN KEUANGAN DAN PEMBANGUNAN', 'PENGADAAN PERANGKAT DAN LISENSI MANAGEMENT APPLIANCE PALO ALTO BPKP', 'Barang', 'E-Purchasing', 'DKI Jakarta, Jakarta Timur (Kota)', 6612341000, 'February 2026', 'APBN - RUPIAH MURNI (A)', 1, 0, '1 Paket', 'Keamanan TI merupakan elemen krusial dalam menjaga keberlangsungan operasional dan perlindungan data organisasi dari ancaman siber. Dalam upaya memastikan keamanan yang optimal, organisasi telah mengimplementasikan solusi keamanan dari Palo Alto Networks, termasuk perangkat firewall PA-5220, PA-220, serta Management Appliance Panorama. Seiring dengan berakhirnya masa berlaku lisensi dan subscription pada perangkat-perangkat tersebut, diperlukan perpanjangan lisensi agar sistem keamanan tetap memperoleh pembaruan perangkat lunak dan patch keamanan dari Palo Alto Networks serta dukungan teknis resmi dari vendor. Perpanjangan ini juga penting untuk memastikan fitur-fitur keamanan utama seperti perlindungan ancaman lanjutan, analisis malware, penyaringan URL, dan layanan pendukung lainnya dapat terus berfungsi secara optimal.', 'Ruang lingkup kegiatan yang harus dilakukan oleh penyedia adalah sebagai berikut meliputi: a. Memiliki surat dukungan dari principal. b. Jaminan pemeliharaan sesuai kontrak, Warranty and On Site dan akan disupport minimal 1 tahun setelah perangkat End of Sale dari Prinsipal. c. Komitmen services untuk instalasi, konfigurasi, dan implementasi perangkat.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2413067);
