INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65877143', 65877143, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'PENGADAAN JASA KONSULTAN PENYUSUNAN DOKUMEN PENGENDALIAN  DAN PENGELOLAAN RISIKO KELEMBAGAAN PEMBANGUNAN  INFRASTRUKTUR', 'Jasa Konsultansi', 'Seleksi', 'DKI Jakarta, Jakarta Pusat (Kota)', 108000000, 'February 2026', 'APBN - RUPIAH MURNI (A)', 0, 1, '10', '1. Penyusunan Rencana Kerja Dalam Rangka Mendukung Perencanaan, Pemantauan dan Pengendalian Kegiatan Kelembagaan Pembangunan Infrastruktur. a) Mengidentifikasi rencana kerja tahunan program dan kegiatan pembangunan infrastruktur yang sedang dan akan dilaksanakan oleh unit kerja, untuk mendukung keterpaduan perencanaan dan pengendalian. b) Mengidentifikasi pembagian peran dan tanggung jawab kelembagaan antar unit/lembaga dalam pelaksanaan program dan kegiatan pembangunan infrastruktur. c) Menyusun rekomendasi strategis awal untuk penguatan peran dan koordinasi kelembagaan dalam pelaksanaan program pembangunan infrastruktur.', '1) Persyaratan Umum a) Memiliki pengalaman kerja paling sedikit 1 (satu) pekerjaan dalam kurun waktu 3 (lima) tahun terakhir dil lingkungan pemerintah maupun swasta, termasuk pengalaman subkontrak. b) Memiliki pengalaman pekerjaan sejenis (jenis pekerjaan, kompleksitas pekerjaan, metodologi, teknologi, atau karakteristik lainnya yang bisa menggambarkan kesamaan). c) Memiliki nilai pekerjaan sejenis tertinggi dalam kurun waktu 10 (sepuluh) tahun terakhir paling kurang sama dengan 50% (lima puluh persen) nilai HPS/Pagu Anggaran. 2) Persyaratan Pendidikan Memiliki latar belakang pendidikan S1 Manajemen dan Kebijakan Publik/ Administrasi Negara/Ilmu Pemerintahan/Hukum dibuktikan dengan Ijazah. 3) Persyaratan Khusus a) Memiliki pengalaman kerja umum minimum 3 (tiga) tahun di bidang sejenis (kelembagaan/perencanaan pembangunan/kebijakan publik) yang dibuktikan melalui pengalaman kerja yang tertera dalam CV. b) Memiliki pengalaman kerja merancang/mengomunikasikan/mengoordinasikan pekerjaan lintas bidang atau lintas level pemerintahan dengan pihak-pihak internal maupun eksternal dalam sebuah program atau kegiatan yang dibuktikan melalui dokumen kontrak kerja.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2414808);
