INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65875375', 65875375, 'analyze_legacy', 'Komisi Pemilihan Umum', 'central', 'KPU  PROVINSI JAWA BARAT', 'Pengadaan Sewa Mobil Roda 4 untuk Pimpinan KPU Provinsi Jawa Barat', 'Jasa Lainnya', 'E-Purchasing', 'Jawa Barat, Bandung (Kota)', 1339200000, 'February 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '( 1, pkt, @ 1339200000 )', '1. Belanja Sewa ( 1, pkt, @ 1339200000 );', '- Sewa 8 unit Fortuner seri terbaru dan tertinggi - 2.8 GR - Warna Putih - NIK 2026 - Jangka Waktu Sewa selama 1 tahun', 1339200000, 'absurd', 'Pengadaan sewa 8 unit SUV premium Fortuner 2.8 GR seri tertinggi untuk pimpinan selama 1 tahun dengan nilai sangat besar menunjukkan fasilitas kendaraan mewah yang berlebihan untuk lembaga penyelenggara pemilu. Spesifikasi kelas atas dan jumlah unit menimbulkan indikasi kuat penggunaan anggaran yang tidak proporsional serta berpotensi memicu kecemburuan publik.', NULL, NULL, 4, 1, 1, 1, 1, 2415908);
