INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65878296', 65878296, 'analyze_legacy', 'Kab. Batanghari', 'kabkota', 'DINAS PEKERJAAN UMUM DAN TATA RUANG', 'DED perencanaan pembangunan Embung Kecamatan batin XXIV', 'Jasa Konsultansi', 'Penunjukan Langsung', 'Jambi, Batang Hari (Kab.)', 100000000, 'April 2026', 'APBD', 1, 1, '1 Paket', 'Dalam rangka memenuhi kebutuhan pangan nasional dan lokal, maka Pemerintah Kabupaten Batanghari telah melaksanakan serangkaian usaha secara terus menerus yang dititik beratkan pada sektor pertanian dan ketahanan pangan, yang berupa pembangunan sarana dan prasarana irigasi permukaan dan irigasi rawa guna meningkatkan produks pangan lokal. Agar kebutuhan pangan lokal dan nasional dapat terpenuhi maka Bidang Sumber Daya Air Dinas Pekerjaan Umum dan Tata Ruang Kabupaten Batanghari berupaya melakukan peningkatan penyediaan layanan sarana dan prasarana irigasi sehingga dapat lebih menunjang sektor pertanian dan ketahanan pangan, dengan cara melakukan evaluasi jaringan Irigasi pada daerah irigasi yang telah dibangun. Dalam melayani kebutuhan air pada daerah irigasi rawa tersebut maka diperlukan tindakan Pembangunan Embung. Tindakan ini dilakukan untuk pemenuhan kebutuhan air irigasi dalam rangka peningkatan produktivitas sawah.', 'Dalam rangka memenuhi kebutuhan pangan nasional dan lokal, maka Pemerintah Kabupaten Batanghari telah melaksanakan serangkaian usaha secara terus menerus yang dititik beratkan pada sektor pertanian dan ketahanan pangan, yang berupa pembangunan sarana dan prasarana irigasi permukaan dan irigasi rawa guna meningkatkan produks pangan lokal. Agar kebutuhan pangan lokal dan nasional dapat terpenuhi maka Bidang Sumber Daya Air Dinas Pekerjaan Umum dan Tata Ruang Kabupaten Batanghari berupaya melakukan peningkatan penyediaan layanan sarana dan prasarana irigasi sehingga dapat lebih menunjang sektor pertanian dan ketahanan pangan, dengan cara melakukan evaluasi jaringan Irigasi pada daerah irigasi yang telah dibangun. Dalam melayani kebutuhan air pada daerah irigasi rawa tersebut maka diperlukan tindakan Pembangunan Embung. Tindakan ini dilakukan untuk pemenuhan kebutuhan air irigasi dalam rangka peningkatan produktivitas sawah.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2416776);
